export const latticePath = (gridSize) => {
  let paths
  for (let i = 1, paths = 1; i <= gridSize; i++) {
    paths = (paths * (gridSize + i)) / i
  }
  // The total number of paths can be found using the binomial coefficient (b+a)/a.
  return paths
}

