  }

  if (!sentence) {
    return null
  }

  const words = sentence.split(' ')
  if (words.length < 2) {
    return words[0]
  }

  const occurrences = {}
  words.forEach((word) => {
    occurrences[word.toLocaleLowerCase()] =
      occurrences[word.toLocaleLowerCase()] + 1 || 1
  })

  const max = Object.keys(occurrences).reduce(
    (n, word) => {
      if (occurrences[word] > n.count) {
        return { word, count: occurrences[word] }
      } else {
        return n
      }
    },
    { word: '', count: 0 }
  )

  return max.word
}

