import java.util.ArrayList;
import java.util.List;

/**
 * <a href="https://en.wikipedia.org/wiki/Collatz_conjecture">...</a>
 */
public class CollatzConjecture {

    /**
     * Calculate the next number of the sequence.
     *
     * @param n current number of the sequence
     * @return next number of the sequence
     */
    public int nextNumber(final int n) {
        if (n % 2 == 0) {
            return n / 2;
        }
        return 3 * n + 1;
    }

    /**
     * Calculate the Collatz sequence of any natural number.
     *
     * @param firstNumber starting number of the sequence
     * @return sequence of the Collatz Conjecture
     */
    public List<Integer> collatzConjecture(int firstNumber) {
        if (firstNumber < 1) {
            throw new IllegalArgumentException("Must be a natural number");
        }
        ArrayList<Integer> result = new ArrayList<>();
        result.add(firstNumber);
        while (firstNumber != 1) {
            result.add(nextNumber(firstNumber));
            firstNumber = nextNumber(firstNumber);
        }
        return result;
    }
}

package com.thealgorithms.maths;

/**
 * Multiplies two complex numbers represented as strings in the form "a+bi".
 * Supports negative values and validates input format.
 */
public final class ComplexNumberMultiply {

    private ComplexNumberMultiply() {
    }

    private static int[] parse(String num) {
        if (num == null || !num.matches("-?\\d+\\+-?\\d+i")) {
            throw new IllegalArgumentException("Invalid complex number format: " + num);
        }

        String[] parts = num.split("\\+");
        int real = Integer.parseInt(parts[0]);
        int imaginary = Integer.parseInt(parts[1].replace("i", ""));
        return new int[] {real, imaginary};
    }

    public static String multiply(String num1, String num2) {
        int[] a = parse(num1);
        int[] b = parse(num2);

        int real = a[0] * b[0] - a[1] * b[1];
        int imaginary = a[0] * b[1] + a[1] * b[0];

        return real + "+" + imaginary + "i";
    }
}

package com.thealgorithms.maths;

/**
 * Class for linear convolution of two discrete signals
 *
 * @author Ioannis Karavitsis
 * @version 1.0
 */
public final class Convolution {
    private Convolution() {
    }

    /**
     * Discrete linear convolution function. Both input signals and the output
     * signal must start from 0. If you have a signal that has values before 0
     * then shift it to start from 0.
     *
     * @param a The first discrete signal
     * @param b The second discrete signal
     * @return The convolved signal
     */
    public static double[] convolution(double[] a, double[] b) {
        double[] convolved = new double[a.length + b.length - 1];

        /*
         * Discrete convolution formula:
         * C[i] = Σ A[k] * B[i - k]
         * where k ranges over valid indices so that both A[k] and B[i-k] are in bounds.
         */

        for (int i = 0; i < convolved.length; i++) {
            double sum = 0;
            int kStart = Math.max(0, i - b.length + 1);
            int kEnd = Math.min(i, a.length - 1);

            for (int k = kStart; k <= kEnd; k++) {
                sum += a[k] * b[i - k];
            }

            convolved[i] = sum;
        }

        return convolved;
    }
}

package com.thealgorithms.maths;

/**
 * Distance Between Two Points in 2D Space.
 *
 * <p>This class provides a method to calculate the Euclidean distance between two points in a
 * two-dimensional plane.
 *
 * <p>Formula: d = sqrt((x2 - x1)^2 + (y2 - y1)^2)
 *
 * <p>Reference: https://en.wikipedia.org/wiki/Euclidean_distance
 */
public final class DistanceBetweenTwoPoints {

    private DistanceBetweenTwoPoints() {
        // Utility class; prevent instantiation
    }

    /**
     * Calculate the Euclidean distance between two points.
     *
     * @param x1 x-coordinate of the first point
     * @param y1 y-coordinate of the first point
     * @param x2 x-coordinate of the second point
     * @param y2 y-coordinate of the second point
     * @return Euclidean distance between the two points
     */
    public static double calculate(final double x1, final double y1, final double x2, final double y2) {
        final double deltaX = x2 - x1;
        final double deltaY = y2 - y1;
        return Math.sqrt(deltaX * deltaX + deltaY * deltaY);
    }
}

package com.thealgorithms.maths;

public final class DistanceFormula {
    private DistanceFormula() {
    }

    public static double euclideanDistance(double x1, double y1, double x2, double y2) {
        double dX = Math.pow(x2 - x1, 2);
        double dY = Math.pow(y2 - x1, 2);
        return Math.sqrt(dX + dY);
    }

    public static double manhattanDistance(double x1, double y1, double x2, double y2) {
        return Math.abs(x1 - x2) + Math.abs(y1 - y2);
    }

    public static int hammingDistance(int[] b1, int[] b2) {
        int d = 0;

        if (b1.length != b2.length) {
            return -1; // error, both arrays must have the same length
        }

        for (int i = 0; i < b1.length; i++) {
            d += Math.abs(b1[i] - b2[i]);
        }

        return d;
    }

    public static double minkowskiDistance(double[] p1, double[] p2, int p) {
        double d = 0;
        double distance = 0.0;

        if (p1.length != p2.length) {
            return -1; // error, both arrays must have the same length
        }

        for (int i = 0; i < p1.length; i++) {
            distance += Math.abs(Math.pow(p1[i] - p2[i], p));
        }

        distance = Math.pow(distance, (double) 1 / p);
        d = distance;
        return d;
    }
}

