/**
 * A number is said to be Dudeney if the sum of the digits, is the cube root of the entered number.
 * Example- Let the number be 512, its sum of digits is 5+1+2=8. The cube root of 512 is also 8.
 *          Since, the sum of the digits is equal to the cube root of the entered number;
 *          it is a Dudeney Number.
 */
public final class DudeneyNumber {
    private DudeneyNumber() {
    }

    // returns True if the number is a Dudeney number and False if it is not a Dudeney number.
    public static boolean isDudeney(final int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("Input must me positive.");
        }
        // Calculating Cube Root
        final int cubeRoot = (int) Math.round(Math.pow(n, 1.0 / 3.0));
        // If the number is not a perfect cube the method returns false.
        if (cubeRoot * cubeRoot * cubeRoot != n) {
            return false;
        }

        // If the cube root of the number is not equal to the sum of its digits, we return false.
        return cubeRoot == SumOfDigits.sumOfDigits(n);
    }
}

package com.thealgorithms.maths;

/**
 * In number theory, an evil number is a non-negative integer that has an even number of 1s in its binary expansion.
 * Non-negative integers that are not evil are called odious numbers.
 *
 * Evil Number Wiki: https://en.wikipedia.org/wiki/Evil_number
 * Odious Number Wiki: https://en.wikipedia.org/wiki/Odious_number
 */
public final class EvilNumber {

    private EvilNumber() {
    }

    // Function to count number of one bits in a number using bitwise operators
    private static int countOneBits(int number) {
        int oneBitCounter = 0;
        while (number > 0) {
            oneBitCounter += number & 1; // increment count if last bit is 1
            number >>= 1; // right shift to next bit
        }
        return oneBitCounter;
    }

    /**
     * Check either {@code number} is an Evil number or Odious number
     *
     * @param number the number
     * @return {@code true} if {@code number} is an Evil number, otherwise false (in case of of Odious number)
     */
    public static boolean isEvilNumber(int number) {
        if (number < 0) {
            throw new IllegalArgumentException("Negative numbers are not allowed.");
        }

        int noOfOneBits = countOneBits(number);
        return noOfOneBits % 2 == 0;
    }
}

